/**
 * Switch's states fixture, with the React fixture's entry names, so a
 * contract's `when <state>` names the same entry in both shells.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/switch.ts`. Never edit it by hand.
 */
import { h } from 'vue'

import type { ComponentStates } from '@polymorph/vue'

import Stack from '../layout/Stack.vue'
import Switch from './Switch.vue'

export const states: ComponentStates = {
  component: 'Switch',
  entries: [
    {
      name: 'off',
      render: (overrides = {}) => h(Switch, { label: 'Desktop notifications', ...overrides }),
      expect: { 'data-state': 'off' },
    },
    {
      name: 'on',
      render: (overrides = {}) =>
        h(Switch, { defaultChecked: true, label: 'Desktop notifications', ...overrides }),
      expect: { 'data-state': 'on' },
    },
    {
      name: 'required — the marker the field row cannot render for it',
      render: (overrides = {}) =>
        h(Switch, { 'aria-required': true, label: 'Accept the terms', ...overrides }),
      expect: { 'data-required': '' },
    },
    {
      name: 'disabled off',
      render: (overrides = {}) =>
        h(Switch, { disabled: true, label: 'Desktop notifications', ...overrides }),
      expect: { 'data-state': 'off', 'data-disabled': '' },
    },
    {
      name: 'disabled on',
      render: (overrides = {}) =>
        h(Switch, {
          disabled: true,
          defaultChecked: true,
          label: 'Desktop notifications',
          ...overrides,
        }),
      expect: { 'data-state': 'on', 'data-disabled': '' },
    },
    {
      name: 'unlabelled — labelled by its context',
      render: (overrides = {}) =>
        h(Switch, { 'aria-label': 'Desktop notifications', ...overrides }),
      expect: { 'aria-label': 'Desktop notifications', 'data-state': 'off' },
    },
    {
      name: 'a settings stack',
      render: (overrides = {}) =>
        h(
          Stack,
          { gap: 3 },
          {
            default: () => [
              h(Switch, { defaultChecked: true, label: 'Desktop notifications', ...overrides }),
              h(Switch, { label: 'Email digest' }),
              h(Switch, { disabled: true, label: 'SMS alerts (not available on this plan)' }),
            ],
          },
        ),
    },
  ],
}
